import SwiftUI
struct AuditLogView: View { @EnvironmentObject var state: AppState; @State private var filter = ""; var filtered: [AuditEvent] { filter.isEmpty ? state.auditEvents : state.auditEvents.filter { $0.eventType.contains(filter) } }; var body: some View { List { TextField("Filter event type", text: $filter); Button("Refresh audit") { Task { await state.loadAudit() } }; ForEach(filtered) { e in VStack(alignment: .leading) { Text(e.eventType).font(.headline); Text("\(e.actor) • \(e.status)").font(.caption); if let result = e.result { Text(result).font(.caption) } } } }.navigationTitle("Audit Log") } }
